insert into public.activities (code, title, category, description, instructions, guiding_questions, duration_label, response_type, just_us, needs, fallback_instructions) values
(43, 'A Day in Your Life Right Now', 'little_adventures', 'Describe an ordinary day in your current life.',
insert into public.play_activities (code, title, category, description, instructions, prompts, minutes, energy, activity_type, moods, materials, mode, style, just_us, needs, fallback_instructions, share_as) values
(101, 'Word Duel', 'guess_discover', 'Teach each other words, then quiz each other.', 'Each teach three words in [a language you speak or are learning]. Say them, act them out, then quiz each other at the end. Pronunciation is judged by laughter.', '{}', 10, 'medium', 'guessing', array['playful','silly'], null, 'call', null, true, array['languages'], 'Each teach three words of slang or childhood words. Act them out, then quiz each other at the end.', 'Live'),
(102, 'Survival Phrase Role-Play', 'silly_random', 'Act out an everyday scene in a language one of you is learning.', 'One of you is the learner, the other plays a waiter, shopkeeper or bus driver. Order food or ask for directions in [a language one of you is learning]. Swap roles.', '{}', 10, 'high', 'talking', array['silly','playful'], null, 'call', null, true, array['languages_learning'], 'Invent a silly made-up language and act out ordering food in it. Swap roles.', 'Live'),
(103, 'Coffee Break, Two Ways', 'virtual_date_night', 'A virtual café date with each place''s drink or snack.', 'Each make a drink or snack that''s typical of [your home country] or [where you live now]. Sit down together, sip slowly and tell the story behind it.', '{}', 15, 'low', 'virtual_date', array['romantic','relaxed'], 'A drink or snack', 'call', null, true, array['home_country', 'current_country'], 'Each make your favourite drink or snack. Sit down together, sip slowly and tell the story behind it.', 'Live'),
(104, 'Walk Me Through Your City', 'virtual_date_night', 'A live walking tour of where one of you is right now.', 'Take your partner on a walk around [your current city]. Show three places you''d take them if they were there, and one place you haven''t explored yet.', '{}', 20, 'medium', 'virtual_date', array['romantic','playful'], null, 'call', null, true, array['current_city'], 'Give your partner a tour of your home, room by room, with a story for each.', 'Live'),
(105, 'Pub Quiz of Our Places', 'guess_discover', 'Quiz each other on the places you''re from and live in.', 'Each write five quiz questions about [your home country] or [your current city]. Take turns asking; the winner picks the next activity.', '{}', 15, 'medium', 'guessing', array['playful'], 'Paper and pen', 'call', null, true, array['home_country', 'current_city'], 'Each write five quiz questions about yourselves. Take turns asking; the winner picks the next activity.', 'Live'),
(106, 'Virtual Day Trip', 'virtual_date_night', 'Pick a place and plan a perfect day there together.', 'Choose somewhere near [their current city] or on your wish list. Look at photos and maps together and plan the perfect day: morning, lunch, afternoon, sunset.', '{}', 20, 'low', 'virtual_date', array['romantic','relaxed'], 'A web browser', 'call', null, true, array['current_city'], 'Choose a dream destination together. Look at photos and maps and plan the perfect day: morning, lunch, afternoon, sunset.', 'Live'),
(107, 'Plan Their Next Stop', 'future_adventures', 'Help plan a real trip they''re thinking about.', 'They share a place they''d like to explore near [their current country]. You research one surprise stop, food or view to add to their plan.', '{}', 20, 'medium', 'talking', array['playful','creative'], null, 'call', null, true, array['current_country'], 'Plan a dream trip together. Each add one surprise stop, food or view.', 'Live'),
(108, 'Home Country Show & Tell', 'heart_to_heart', 'Three objects that explain where you come from.', 'Each find three things that say something about [your home country] or your childhood there, and tell their stories.', '{}', 15, 'low', 'storytelling', array['deep','relaxed'], 'Three objects', 'call', null, true, array['home_country'], 'Each find three objects that explain who you are, and tell their stories.', 'Live'),
(109, 'Cook a Dish From Their World', 'virtual_date_night', 'Cook something from your partner''s world while they coach.', 'Your partner picks a simple dish from [their home country] or [where they live now] and coaches you through it live. Eat it together on camera.', '{}', 30, 'medium', 'virtual_date', array['romantic','playful'], 'Simple ingredients', 'call', null, true, array['home_country', 'current_country'], 'Cook each other''s comfort food together on camera, then eat together.', 'Live'),
(110, 'What This Chapter Is Teaching You', 'heart_to_heart', 'Talk about what your current life is teaching you.', 'Take turns: what has [your current situation] taught you about yourself? What surprised you? What will you take with you?', '{}', 15, 'low', 'talking', array['deep'], null, 'call', null, true, array['situation'], 'Take turns: what has this year taught you about yourself? What surprised you? What will you take with you?', 'Live'),
(111, 'Idiom Swap', 'silly_random', 'Explain a strange saying; your partner guesses its meaning.', 'Share a weird idiom from [a language you speak], translated word for word. Your partner guesses what it really means.', '{}', 10, 'medium', 'guessing', array['silly','playful'], null, 'call', null, true, array['languages_spoken'], 'Share a strange family saying. Your partner guesses what it really means.', 'Live'),
(112, 'Then, Now, Next', 'future_adventures', 'Map your story: where you were, where you are, where you''re going.', 'Together, retell where you each were when you met, where you are now ([your current city] and [their current city]) and where you''d love to be next.', '{}', 15, 'low', 'storytelling', array['romantic','deep'], null, 'call', null, true, array['current_city'], 'Together, retell where you each were when you met, where you are now and where you''d love to be next.', 'Live');
insert into public.play_activities (code, title, category, description, instructions, prompts, minutes, energy, activity_type, moods, materials, mode, style, just_us, needs, fallback_instructions, share_as) values
(113, 'Postcard From Your Week', 'virtual_date_night', 'One photo and one line from your week.', 'Take one photo that sums up your week in [your current city], add one line. Both postcards open when you''ve both sent yours.', '{}', 5, 'low', 'photo', array['romantic','relaxed'], null, 'apart', 'solo', true, array['current_city'], 'Take one photo that sums up your week and add one line. Both postcards open when you''ve both sent yours.', 'Photo + text'),
(114, 'Word of the Week Relay', 'guess_discover', 'Swap one word a week and use each other''s word.', 'Each week, post one word from [a language you speak or are learning]. Your partner has to use it in a sentence before the week ends.', '{}', 5, 'low', 'writing', array['playful'], null, 'apart', 'relay', true, array['languages'], 'Each week, post one unusual English word. Your partner has to use it in a sentence before the week ends.', 'Text (relay)'),
(115, 'A Little Piece of Home', 'heart_to_heart', 'Find something nearby that reminds you of your partner''s world.', 'Find something in [your current city] that reminds you of [their home country] or of them. Photograph it and say why.', '{}', 10, 'low', 'photo', array['romantic'], null, 'apart', 'solo', true, array['current_city', 'partner_home_country'], 'Find something near you that reminds you of your partner. Photograph it and say why.', 'Photo + text'),
(116, 'New-to-Me Snack Review', 'silly_random', 'Try a snack that''s new to you and review it.', 'Try a snack you''ve never had in [your current country]. Write a dramatic food-critic review with a score out of 10.', '{}', 10, 'medium', 'photo', array['silly','playful'], 'A new snack', 'apart', 'solo', true, array['current_country'], 'Try a snack you''ve never had. Write a dramatic food-critic review with a score out of 10.', 'Photo + text'),
(117, 'Explain It in a Minute', 'guess_discover', 'Explain something from your studies or work, simply.', 'Explain one thing from [your work or studies] in simple words — as if to a curious 10-year-old. Your partner asks one follow-up question.', '{}', 10, 'low', 'writing', array['deep','creative'], null, 'apart', 'solo', true, array['institution_or_situation'], 'Explain any topic you love in simple words — as if to a curious 10-year-old. Your partner asks one follow-up question.', 'Text'),
(118, 'Culture Swap Challenge', 'silly_random', 'Try one small custom from your partner''s world this week.', 'Your partner picks one small thing from [their home country] for you to try — a food, a phrase, a habit. Report back with a photo or story.', '{}', 15, 'medium', 'photo', array['playful','silly'], null, 'apart', 'solo', true, array['partner_home_country'], 'Your partner picks one of their small habits for you to try this week. Report back with a photo or story.', 'Photo + text'),
(119, 'My Language Fail of the Week', 'silly_random', 'Share your funniest language mistake.', 'Share the funniest mistake you made this week in [a language you''re learning] — or a word you keep getting wrong.', '{}', 5, 'low', 'writing', array['silly'], null, 'apart', 'solo', true, array['my_languages_learning'], 'Share your funniest mix-up or misunderstanding of the week.', 'Text'),
(120, 'Same Thing, Two Places', 'creative_chaos', 'Photograph the same everyday thing where you each are.', 'Pick a thing together (a bus ticket, a coffee, a supermarket shelf, a door). Photograph it in [your current city]. Reveal both and spot the differences.', '{}', 10, 'low', 'photo', array['playful','creative'], null, 'apart', 'same', true, array['current_city'], 'Pick an everyday thing together (a cup, a door, a view). Photograph yours, then reveal both and spot the differences.', 'Photo'),
(121, 'Our Places List', 'future_adventures', 'A list you build together over time: places you''ve been and want to go.', 'Whenever you like, add a place you''ve lived, visited or dream of. Add one line about why. Watch your shared list grow.', '{}', 5, 'low', 'writing', array['romantic','relaxed'], null, 'apart', 'relay', true, '{}', null, 'Text (relay)');
insert into public.play_activities (code, title, category, description, instructions, prompts, minutes, energy, activity_type, moods, materials, mode, style, just_us, share_as) values
(131, 'Photo Prompt Hunt', 'creative_chaos', 'Both get the same photo prompt; reveal together.', 'Each take a photo that fits the prompt, whenever suits you. Both photos open once you''ve both shared.', array['Something red', 'A shadow', 'Your view right now', 'Something old', 'Something that made you smile'], 5, 'low', 'photo', array['playful','creative'], null, 'apart', 'solo', false, 'Photo'),
(132, 'Relay Story', 'creative_chaos', 'Write a story together, one turn at a time.', 'One of you writes the opening paragraph. The other adds the next whenever they have a moment. Aim for six turns over the week.', array['Opening idea: "The postcard arrived three years late."'], 5, 'low', 'writing', array['creative','silly'], null, 'apart', 'relay', false, 'Text (relay)'),
(133, 'Same Film, Separate Sofas', 'virtual_date_night', 'Watch the same film or episode at different times, then compare.', 'Pick something together. Watch it whenever suits you. Each share a rating, your favourite moment and one question for the other.', '{}', 30, 'low', 'writing', array['relaxed','romantic'], 'The same film or show', 'apart', 'same', false, 'Text'),
(134, 'Playlist Swap', 'virtual_date_night', 'Build a shared playlist across the week.', 'Each add three songs over the week without explaining. At the end, guess why the other chose theirs.', '{}', 10, 'low', 'writing', array['romantic','playful'], 'Music app', 'apart', 'relay', false, 'Link + text'),
(135, 'Sketch a Memory', 'creative_chaos', 'Draw a moment you''ve shared, from memory.', 'Each draw the same shared memory without talking about it first. Reveal and compare what you each remembered.', '{}', 10, 'low', 'drawing', array['romantic','creative'], 'Paper and pen, or the drawing pad', 'apart', 'solo', false, 'Drawing'),
(136, 'Bedtime Story Drop', 'heart_to_heart', 'Leave a tiny story for your partner''s bedtime.', 'Write a five-line bedtime story starring the two of you, for your partner to read at their night-time.', '{}', 10, 'low', 'writing', array['romantic','relaxed'], null, 'apart', 'solo', false, 'Text (voice later)'),
(137, 'Little Surprise Mission', 'heart_to_heart', 'Plan a small surprise for your partner this week.', 'Secretly send something small: a song, a photo, a meme, a note, a delivery. Log what you sent so it''s saved for both of you.', '{}', 15, 'low', 'writing', array['romantic','playful'], null, 'apart', 'solo', false, 'Text + photo'),
(138, 'Kindness Quest', 'heart_to_heart', 'Do one kind thing for someone, then tell each other.', 'Each do one small kind thing for a stranger or friend this week. Share what you did and how it felt.', '{}', 10, 'low', 'writing', array['deep','relaxed'], null, 'apart', 'solo', false, 'Text'),
(139, 'What''s on My Desk?', 'silly_random', 'Photograph your desk or bag exactly as it is.', 'No tidying allowed! Your partner picks one item and asks for its story.', '{}', 5, 'low', 'photo', array['silly','playful'], null, 'apart', 'solo', false, 'Photo + text'),
(140, 'Read the Same Thing', 'guess_discover', 'Read the same article, essay or short story and react.', 'One of you picks something to read. Both write three lines: what surprised you, what you disagree with, what you''d ask the author.', '{}', 15, 'low', 'research', array['deep'], null, 'apart', 'same', false, 'Link + text'),
(141, 'Ten-Minute Research Drop', 'guess_discover', 'Research a random question, then send a tiny summary.', 'Take a question you''re curious about. Spend ten minutes on it and share three lines and a source link.', array['Why do we yawn?', 'How do cats always land on their feet?', 'Who invented the postcard?'], 10, 'low', 'research', array['deep','creative'], null, 'apart', 'solo', false, 'Text + link'),
(142, 'Question Jar Relay', 'heart_to_heart', 'Leave questions for each other to answer whenever.', 'Each add one question to the jar. Answer the other''s whenever you like — and leave a new one.', '{}', 5, 'low', 'writing', array['deep','playful'], null, 'apart', 'relay', false, 'Text (relay)'),
(143, 'Comic Strip Relay', 'creative_chaos', 'Draw a comic one panel at a time.', 'You draw panel one, they draw panel two, you finish panel three. No planning allowed.', '{}', 10, 'medium', 'drawing', array['silly','creative'], 'Paper and pen, or the drawing pad', 'apart', 'relay', false, 'Drawing (relay)'),
(144, 'Highlight of the Day Week', 'heart_to_heart', 'One line about the best part of each day, for a week.', 'Every day for seven days, each write one line about your highlight. Read the whole week together on Sunday.', '{}', 5, 'low', 'writing', array['relaxed','romantic'], null, 'apart', 'relay', false, 'Text (relay)'),
(145, 'Alphabet Photo Hunt', 'creative_chaos', 'Spell your partner''s name with letters you find around you.', 'Find letter shapes in signs, objects or nature, photograph them, and spell out your partner''s name.', '{}', 15, 'medium', 'photo', array['playful','creative'], null, 'apart', 'solo', false, 'Photo'),
(146, 'Recreate an Old Photo', 'silly_random', 'Recreate a photo of yourself from years ago.', 'Find an old photo of yourself and recreate it as closely as you can. Share both side by side.', '{}', 15, 'medium', 'photo', array['silly','playful'], 'An old photo', 'apart', 'solo', false, 'Photo'),
(147, 'Guess Where I Am', 'guess_discover', 'A close-up photo of where you are — your partner guesses.', 'Send a zoomed-in photo of your surroundings. Your partner gets three guesses before you reveal.', '{}', 5, 'low', 'photo', array['playful'], null, 'apart', 'relay', false, 'Photo'),
(148, 'Mood in Three Songs', 'virtual_date_night', 'Describe your week in three songs.', 'Pick three songs that sum up your week: the start, the middle and right now. Explain one of them.', '{}', 10, 'low', 'writing', array['relaxed','romantic'], 'Music app', 'apart', 'solo', false, 'Link + text'),
(149, 'A Letter for Later', 'future_adventures', 'Write a letter to open on your next visit.', 'Write a letter your partner opens only when you''re next together. It stays folded away until you both choose to open it.', '{}', 20, 'low', 'writing', array['romantic','deep'], null, 'apart', 'solo', false, 'Text'),
(150, 'Tiny Challenge Swap', 'silly_random', 'Set each other a five-minute challenge.', 'Each set one small, free challenge for the other — draw your breakfast, learn a card trick, compliment a stranger. Share proof.', '{}', 5, 'medium', 'photo', array['silly','playful'], null, 'apart', 'solo', false, 'Photo + text');
