-- Our Little Ritual — approved personalisation content (Vee, 15 Nov 2026).
-- [tokens] are filled from both profiles on each phone; fallback text is used
-- when a needed detail is missing. Nothing here hardcodes a place, school or language.

-- --------------------------------------------- approved edits to existing Play activities
update public.play_activities set prompts = array['suitcase', 'jealousy', 'sunrise', 'pineapple', 'lighthouse', 'hiccup', 'homesick', 'umbrella'] where code = 2;
update public.play_activities set prompts = array['Fun when you live in different countries'] where code = 14;
update public.play_activities set instructions = 'Say a word in a language you speak or are learning and give three possible meanings. Partner picks the right one, then tries to say it.' where code = 15;
update public.play_activities set instructions = 'Teach each other a tongue twister in any language you speak or are learning. Try it three times, faster each time.' where code = 62;

-- --------------------------------------------- Just us weekly rituals (one per category, so the rotation stays balanced)
 'Walk your partner through a normal day in [your current situation] in [your current city] — from waking up to falling asleep. Add a photo if you like.',
 array['What''s the first thing you see in the morning?', 'What surprised you this week?'], '15 min', 'text_photo', true, array['situation', 'current_city'],
 'Walk your partner through a normal day this week — from waking up to falling asleep. Add a photo if you like.'),
(44, 'Three Things I''ve Learned Here', 'just_for_fun', 'What your current place has taught you lately.',
 'Share three things you''ve learned living in [your current city] — big, small or funny.',
 array['Something practical', 'Something about people', 'Something about yourself'], '10 min', 'text', true, array['current_city'],
 'Share three things you''ve learned this month — big, small or funny.'),
(45, 'Bring Me Along', 'creative_corner', 'Three places you''d take your partner.',
 'Photograph or describe three places in [your current city] you''d take your partner on their first day visiting.',
 array['A place to eat', 'A place to sit and talk', 'A place that feels like you'], '15 min', 'text_photo', true, array['current_city'],
 'Photograph or describe three places near you that you''d love to show your partner.'),
(46, 'A Tradition From Home', 'our_memories', 'Share a tradition you''d love your partner to experience.',
 'Describe one tradition from [your home country] you''d love to share with your partner one day, and how you''d do it together.',
 array['When does it happen?', 'What would you cook, wear or sing?'], '15 min', 'text_photo', true, array['home_country'],
 'Describe a family tradition you''d love to share with your partner one day, and how you''d do it together.'),
(47, 'Language Love Note', 'heart_to_heart', 'A short love note with words from your partner''s languages.',
 'Write a short love note that uses at least three words in [a language your partner speaks or is learning]. They translate it at the reveal.',
 array['Start with a word they taught you', 'End with a word you looked up'], '10 min', 'text', true, array['partner_languages'],
 'Write a short love note that uses three words you''ve never used before. Your partner guesses which ones at the reveal.'),
(48, 'Where Should We Go Together?', 'our_future', 'One place to explore together, and why.',
 'Pick one place in the world you''d love to explore together. Explain what you''d do there and why it''s for the two of you.',
 array['What would you eat first?', 'What would you bring home?'], '10 min', 'text_photo', true, '{}', null);

